contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address u, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(u != address(this));

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint preU = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint preSelf = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postU = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint postSelf = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted ? (postU == preU && postSelf == 0) : (postU == preU && postSelf == preSelf));
    }
}

